import sys
import math

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        if self.n == 0:
            self.tree = []
            return
        self.tree = [0] * (4 * self.n)
        self._build(data, 0, 0, self.n - 1)

    def _build(self, data, node, start, end):
        if start == end:
            self.tree[node] = data[start]
        else:
            mid = (start + end) // 2
            self._build(data, 2 * node + 1, start, mid)
            self._build(data, 2 * node + 2, mid + 1, end)
            self.tree[node] = math.gcd(self.tree[2 * node + 1], self.tree[2 * node + 2])

    def _query(self, node, start, end, l, r):
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        left_gcd = self._query(2 * node + 1, start, mid, l, r)
        right_gcd = self._query(2 * node + 2, mid + 1, end, l, r)
        return math.gcd(left_gcd, right_gcd)

    def query(self, l, r):
        if self.n == 0:
            return 0
        return self._query(0, 0, self.n - 1, l - 1, r - 1)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    if n == 0:
        a = []
    else:
        a = list(map(int, data[1:1 + n]))

    idx = 1 + n
    q = int(data[idx])
    idx += 1

    queries = []
    for i in range(q):
        l = int(data[idx])
        r = int(data[idx + 1])
        queries.append((l, r))
        idx += 2

    if n == 0:
        for _ in queries:
            print(-1)
        return

    seg_tree = SegmentTree(a)

    for l, r in queries:
        result = seg_tree.query(l, r)
        print(result)

if __name__ == "__main__":
    main()
